import React from "react";

export default function About(){
  return (
    <div className="container">
      <div className="card">
        <h2 style={{color:"#005baa"}}>About the School</h2>
        <p>Founded in 2000, Kendriya Vidyalaya provides modern facilities and holistic education to students...</p>

        <div style={{display:"flex",gap:12,flexWrap:"wrap",marginTop:12}}>
          <img src="https://www.gipsm.in/images/banner1.jpg" style={{width:280,height:160,objectFit:"cover",borderRadius:6}} alt="img1"/>
          <img src="https://www.gipsm.in/images/images1.jpg" style={{width:280,height:160,objectFit:"cover",borderRadius:6}} alt="img2"/>
        </div>
      </div>
    </div>
  );
}
